args.content:
package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

type jsonTheme struct {
	colors      map[fyne.ThemeColorName]color.Color
	colorsDark  map[fyne.ThemeColorName]color.Color
	colorsLight map[fyne.ThemeColorName]color.Color
	sizes       map[fyne.ThemeSizeName]float32
	fonts       map[string]fyne.Resource
	icons       map[fyne.ThemeIconName]fyne.Resource
	fallback    fyne.Theme
}

type jsonThemeData struct {
	Colors      map[string]string `json:"Colors"`
	ColorsDark  map[string]string `json:"Colors-dark"`
	ColorsLight map[string]string `json:"Colors-light"`
	Sizes       map[string]float32 `json:"Sizes"`
	Fonts       map[string]string `json:"Fonts"`
	Icons       map[string]string `json:"Icons"`
}

// FromJSON parses a JSON string and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// The JSON structure supports:
//   - "Colors": map of color name to hex string (applied regardless of variant)
//   - "Colors-dark": map of color name to hex string (dark variant only)
//   - "Colors-light": map of color name to hex string (light variant only)
//   - "Sizes": map of size name to float32 value
//   - "Fonts": map of font style ("regular", "bold", "boldItalic", "monospace") to URI
//   - "Icons": map of icon name to URI
//
// Hex colors support 3, 4, 6, or 8 digits with optional "#" prefix.
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var data jsonThemeData
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&data); err != nil {
		return DefaultTheme(), fmt.Errorf("failed to parse JSON theme: %w", err)
	}

	theme := &jsonTheme{
		colors:      make(map[fyne.ThemeColorName]color.Color),
		colorsDark:  make(map[fyne.ThemeColorName]color.Color),
		colorsLight: make(map[fyne.ThemeColorName]color.Color),
		sizes:       make(map[fyne.ThemeSizeName]float32),
		fonts:       make(map[string]fyne.Resource),
		icons:       make(map[fyne.ThemeIconName]fyne.Resource),
		fallback:    DefaultTheme(),
	}

	var parseErr error

	// Parse generic colors
	for name, hexStr := range data.Colors {
		c, err := parseHexColor(hexStr)
		if err != nil {
			parseErr = fmt.Errorf("invalid color %q: %w", name, err)
			continue
		}
		theme.colors[fyne.ThemeColorName(name)] = c
	}

	// Parse dark variant colors
	for name, hexStr := range data.ColorsDark {
		c, err := parseHexColor(hexStr)
		if err != nil {
			parseErr = fmt.Errorf("invalid dark color %q: %w", name, err)
			continue
		}
		theme.colorsDark[fyne.ThemeColorName(name)] = c
	}

	// Parse light variant colors
	for name, hexStr := range data.ColorsLight {
		c, err := parseHexColor(hexStr)
		if err != nil {
			parseErr = fmt.Errorf("invalid light color %q: %w", name, err)
			continue
		}
		theme.colorsLight[fyne.ThemeColorName(name)] = c
	}

	// Parse sizes
	for name, value := range data.Sizes {
		theme.sizes[fyne.ThemeSizeName(name)] = value
	}

	// Parse fonts
	for style, uri := range data.Fonts {
		res, err := loadResource(uri)
		if err != nil {
			parseErr = fmt.Errorf("failed to load font %q: %w", style, err)
			continue
		}
		theme.fonts[style] = res
	}

	// Parse icons
	for name, uri := range data.Icons {
		res, err := loadResource(uri)
		if err != nil {
			parseErr = fmt.Errorf("failed to load icon %q: %w", name, err)
			continue
		}
		theme.icons[fyne.ThemeIconName(name)] = res
	}

	return theme, parseErr
}

func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Check variant-specific colors first
	if variant == fyne.VariantDark {
		if c, ok := t.colorsDark[name]; ok {
			return c
		}
	} else if variant == fyne.VariantLight {
		if c, ok := t.colorsLight[name]; ok {
			return c
		}
	}

	// Check generic colors
	if c, ok := t.colors[name]; ok {
		return c
	}

	// Fallback to default theme
	return t.fallback.Color(name, variant)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	var key string
	if style.Bold && style.Italic {
		key = "boldItalic"
	} else if style.Bold {
		key = "bold"
	} else if style.Monospace {
		key = "monospace"
	} else {
		key = "regular"
	}

	if res, ok := t.fonts[key]; ok {
		return res
	}

	return t.fallback.Font(style)
}

func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if res, ok := t.icons[name]; ok {
		return res
	}

	return t.fallback.Icon(name)
}

func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if size, ok := t.sizes[name]; ok {
		return size
	}

	return t.fallback.Size(name)
}

// parseHexColor parses a hex color string with optional "#" prefix.
// Supports 3, 4, 6, or 8 digit formats.
func parseHexColor(hex string) (color.Color, error) {
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8 = 0, 0, 0, 255

	switch len(hex) {
	case 3:
		// RGB: #abc -> #aabbcc
		vals, err := parseHexDigits(hex, 3)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0] | (vals[0] << 4)
		g = vals[1] | (vals[1] << 4)
		b = vals[2] | (vals[2] << 4)

	case 4:
		// RGBA: #abcd -> #aabbccdd
		vals, err := parseHexDigits(hex, 4)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0] | (vals[0] << 4)
		g = vals[1] | (vals[1] << 4)
		b = vals[2] | (vals[2] << 4)
		a = vals[3] | (vals[3] << 4)

	case 6:
		// RRGGBB
		val, err := strconv.ParseUint(hex, 16, 32)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %w", err)
		}
		r = uint8(val >> 16)
		g = uint8(val >> 8)
		b = uint8(val)

	case 8:
		// RRGGBBAA
		val, err := strconv.ParseUint(hex, 16, 32)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %w", err)
		}
		r = uint8(val >> 24)
		g = uint8(val >> 16)
		b = uint8(val >> 8)
		a = uint8(val)

	default:
		return color.Transparent, fmt.Errorf("invalid hex color length: %d", len(hex))
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

func parseHexDigits(hex string, count int) ([]uint8, error) {
	vals := make([]uint8, count)
	for i := 0; i < count; i++ {
		val, err := strconv.ParseUint(hex[i:i+1], 16, 8)
		if err != nil {
			return nil, fmt.Errorf("invalid hex digit: %w", err)
		}
		vals[i] = uint8(val)
	}
	return vals, nil
}

func loadResource(uri string) (fyne.Resource, error) {
	u, err := storage.ParseURI(uri)
	if err != nil {
		return nil, fmt.Errorf("invalid URI: %w", err)
	}

	reader, err := storage.Reader(u)
	if err != nil {
		return nil, fmt.Errorf("failed to read resource: %w", err)
	}
	defer reader.Close()

	data, err := io.ReadAll(reader)
	if err != nil {
		return nil, fmt.Errorf("failed to read resource data: %w", err)
	}

	return fyne.NewStaticResource(u.Name(), data), nil
}

