package binding

import (
	"fmt"
	"sync"
)

// StringFormat creates a new String binding that formats its content using fmt.Sprintf.
// It takes a format string and a list of DataItem bindings as sources.
// When any source changes, the output is automatically reformatted.
//
// Since: 2.2
func StringFormat(format string, b ...DataItem) String {
	if len(b) == 0 {
		return NewString()
	}

	result := &stringFormatBinding{
		format:  format,
		sources: b,
	}
	result.ExtendBase(result)

	for _, source := range b {
		source.AddListener(result)
	}

	return result
}

type stringFormatBinding struct {
	base

	format  string
	sources []DataItem
	mu      sync.RWMutex
}

func (s *stringFormatBinding) Get() (string, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		if untypedSource, ok := source.(Untyped); ok {
			val, err := untypedSource.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		} else if stringSource, ok := source.(String); ok {
			val, err := stringSource.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		} else if intSource, ok := source.(Int); ok {
			val, err := intSource.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		} else if floatSource, ok := source.(Float); ok {
			val, err := floatSource.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		} else if boolSource, ok := source.(Bool); ok {
			val, err := boolSource.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		} else {
			return "", fmt.Errorf("unsupported binding type")
		}
	}

	return fmt.Sprintf(s.format, values...), nil
}

func (s *stringFormatBinding) Set(string) error {
	return fmt.Errorf("cannot set value on a format binding")
}

func (s *stringFormatBinding) DataChanged() {
	s.trigger()
}

