func (jt *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Check variant-specific colors first
	if variant == theme.VariantDark {
		if col, ok := jt.colorsDark[name]; ok {
			return col
		}
	}
	if variant == theme.VariantLight {
		if col, ok := jt.colorsLight[name]; ok {
			return col
		}
	}

	// Fall back to shared colors
	if col, ok := jt.colors[name]; ok {
		return col
	}

	// Fall back to default theme
	return theme.DefaultTheme().Color(name, variant)
}

