package validation

import "fyne.io/fyne/v2"

// NewAllStrings creates a validator that checks if the input string is one of the provided options.
// This is useful for dropdown selections or any case where input must match a predefined set.
//
// Since: 2.2
func NewAllStrings(valid []string) fyne.StringValidator {
	return func(input string) error {
		for _, v := range valid {
			if input == v {
				return nil
			}
		}
		return &validationError{message: "Value not in allowed list"}
	}
}

type validationError struct {
	message string
}

func (e *validationError) Error() string {
	return e.message
}

